/* generated by wf assemble from webflow/build/tailoring/*.js in spec order; edit the fragments, never this file */
/* wf:section hero (webflow/build/tailoring/hero.js) */
try {
(() => {
/* Source selection only. Shared helpers own playback, pause, and cinema motion. */
(() => {
  const film = document.querySelector('.wf-tailoring-hero-film');
  if (!film) return;
  const mobile = matchMedia('(max-width: 650px)');
  const source = () => {
    // Literal paths: scripts/build-site.mjs only publishes files named in full.
    film.dataset.src = mobile.matches ? 'assets/tailoring-r4-hero-matched-r45-mobile.mp4' : 'assets/tailoring-r4-hero-matched-r45.mp4';
    film.dataset.poster = mobile.matches ? 'assets/tailoring-r4-hero-matched-r45-mobile-poster.webp' : 'assets/tailoring-r4-hero-matched-r45-poster.webp';
    film.poster = film.dataset.poster;
    window.GMPremium?.syncMedia();
  };
  source();
  mobile.addEventListener('change', source);
})();
})();
} catch (e) { console.error("wf:section hero", e); }

/* wf:section fixes (webflow/build/tailoring/fixes.js) */
try {
(() => {
(() => {
 const root = document.querySelector('.wf-tailoring-fixes');
 if (!root) return;
 root.querySelectorAll('[data-adjust]').forEach(input => {
  const key = input.dataset.adjust;
  const specimen = input.closest('[data-specimen]');
  const drawing = specimen.querySelector('[data-move]');
  const control = input.closest('.wf-tailoring-fixes-control');
  const output = control.querySelector('output');
  const reset = control.querySelector('button');
  output.setAttribute('for',input.id);
  // Native range feedback announces the value; the visible output avoids a duplicate live announcement.
  output.setAttribute('aria-live','off');
  reset.setAttribute('aria-label','Reset ' + key + ' illustration');
  const update = () => {
   const amount = Number(input.value) / 100;
   drawing.style.transform = key === 'waist' ? 'scaleX(' + (1.1 - amount * .2) + ')' : 'translateY(' + ((.5 - amount) * 60) + 'px)';
   const label = key === 'waist' ? (amount < .34 ? 'More room' : amount > .66 ? 'Closer' : 'Medium') : (amount < .34 ? 'Longer' : amount > .66 ? 'Shorter' : 'Medium');
   output.value = label;
   input.setAttribute('aria-valuetext',label + ' ' + key + ' illustration');
   input.style.setProperty('--range-progress',input.value + '%');
   reset.disabled = Number(input.value) === 50;
  };
  control.hidden = false;
  input.addEventListener('input',update);
  reset.addEventListener('click',() => {
   input.value = 50;
   update();
   input.focus({preventScroll:true});
  });
  update();
 });
})();
})();
} catch (e) { console.error("wf:section fixes", e); }

/* wf:section fitting (webflow/build/tailoring/fitting.js) */
try {
(() => {
(() => {
  const root = document.querySelector('.wf-tailoring-fitting');
  if (!root) return;
  const video = root.querySelector('video');
  const mobile = matchMedia('(max-width: 760px)');
  const reduced = matchMedia('(prefers-reduced-motion: reduce)');
  // Runs before the shared lifecycle hydrates the lazy source.
  if (mobile.matches) {
    video.dataset.src = video.dataset.srcMobile;
    video.dataset.poster = video.dataset.posterMobile;
    video.poster = video.dataset.poster;
  }
  const steps = [...root.querySelectorAll('[data-fitting-step]')];
  const surface = root.querySelector('.wf-tailoring-fitting-surface');
  const marks = [...root.querySelectorAll('.wf-tailoring-fitting-progress span')];
  let frame = 0;
  let current = -1;
  function update() {
    frame = 0;
    const enabled = !reduced.matches && innerHeight >= 620;
    root.classList.toggle('is-sequenced', enabled);
    if (!enabled) { current = -1; return; }
    const rect = root.getBoundingClientRect();
    const travel = Math.max(1, rect.height - surface.offsetHeight);
    const progress = Math.max(0, Math.min(1, -rect.top / travel));
    const next = Math.min(2, Math.floor(progress * 3));
    if (next === current) return;
    current = next;
    steps.forEach((step, index) => step.classList.toggle('is-current', index === next));
    marks.forEach((mark, index) => mark.classList.toggle('is-current', index === next));
  }
  function schedule() { if (!frame) frame = requestAnimationFrame(update); }
  addEventListener('scroll', schedule, { passive: true });
  addEventListener('resize', schedule, { passive: true });
  mobile.addEventListener('change', schedule);
  reduced.addEventListener('change', schedule);
  update();
})();
})();
} catch (e) { console.error("wf:section fitting", e); }

